float circle(vec2 st, float r)
{
    return 1.0 - smoothstep(r, r + 0.01, length(st));
}
float rect(vec2 st, vec2 size)
{
   st+=1.5*((size));
    size = 0.25*(1.0-size);

    vec2 uv = smoothstep(size, size+0.01, st*(1.0-st));

    return uv.x*uv.y;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y;


    vec3 rec_color = vec3(1.0, 0.0,0.0); 
    vec3 circle_color = vec3(0.0, 0.0,1.0);

    //translating the coordinate system

    vec2 translate = (vec2((sin(iTime)),0.0));

    st += translate;
    //white background
    vec3 color=vec3(1.0f);


    //car body
    color = mix(color, rec_color, rect(st, vec2(0.5, 0.2))); 
    color = mix(color, rec_color, rect(st+vec2(0.6, -0.2), vec2(0.2, 0.2)));

    //wheels
    color = mix(color, circle_color, circle(st, 0.2));
    st+=vec2(0.5, 0.);
    color = mix(color, circle_color, circle(st, 0.2));

    fragColor = vec4(color, 1.0);
}
